import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int n = Integer.parseInt(st.nextToken()); // number of commands
        int m = Integer.parseInt(st.nextToken()); // number of skill types

        // skill points required for each command
        int[] required = new int[n];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            required[i] = Integer.parseInt(st.nextToken());
        }

        // adjacency list for prerequisites
        List<Integer>[] prereq = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            prereq[i] = new ArrayList<>();
        }

        int[] indeg = new int[n];
        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            int k = Integer.parseInt(st.nextToken());
            for (int j = 0; j < k; j++) {
                int p = Integer.parseInt(st.nextToken()) - 1;
                prereq[p].add(i);
                indeg[i]++;
            }
        }

        // available skill points
        int[] points = new int[m];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < m; i++) {
            points[i] = Integer.parseInt(st.nextToken());
        }

        // Topological sort using Kahn's algorithm
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            if (indeg[i] == 0) {
                queue.add(i);
            }
        }

        int[] learned = new int[n]; // 0 = not learned, 1 = learned
        int[] allocated = new int[m]; // allocated points per skill type

        while (!queue.isEmpty()) {
            int cmd = queue.poll();

            // Check if we can learn this command
            int type = required[cmd];
            if (allocated[type] < points[type]) {
                allocated[type]++;
                learned[cmd] = 1;
            } else {
                // Cannot learn this command
                System.out.println("No");
                return;
            }

            // Reduce indegree of dependent commands
            for (int next : prereq[cmd]) {
                indeg[next]--;
                if (indeg[next] == 0) {
                    queue.add(next);
                }
            }
        }

        // Check if all commands are learned
        for (int i = 0; i < n; i++) {
            if (learned[i] == 0) {
                System.out.println("No");
                return;
            }
        }

        System.out.println("Yes");
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt(); // number of skills
        int P = sc.nextInt(); // total skill points
        int M = sc.nextInt(); // number of commands

        int[] minRequired = new int[N + 1];

        for (int i = 0; i < M; i++) {
            int skill = sc.nextInt();
            int value = sc.nextInt();
            minRequired[skill] = Math.max(minRequired[skill], value);
        }

        long total = 0;
        for (int i = 1; i <= N; i++) {
            total += minRequired[i];
        }

        if (total <= P) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }
}

